SELECT order_cohort, cancelled_amount, min_order_date FROM (SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, SUM(CASE WHEN status = 'CANCELLED' THEN amount ELSE 0 END) AS cancelled_amount, MIN(order_date) AS min_order_date FROM orders GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS agg WHERE cancelled_amount >= 67 ORDER BY cancelled_amount DESC, order_cohort ASC
